const $ = id => document.getElementById(id);
// heavy re-render: 100 rows, 20 random cells every 100ms, full tbody rebuild every 1s
const tb = $('tb'); let gen = 0;
function rebuild() {
  gen++;
  const frag = document.createDocumentFragment();
  for (let i = 0; i < 100; i++) {
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${i}</td><td>row-${i}-g${gen}</td><td>${(Math.random()*1000).toFixed(1)}</td><td class="d">0</td><td><span class="pill">${['ok','warn','err'][(i+gen)%3]}</span></td>`;
    frag.appendChild(tr);
  }
  tb.replaceChildren(frag);
}
rebuild(); setInterval(rebuild, 1000);
setInterval(() => {
  for (let k = 0; k < 20; k++) {
    const r = tb.rows[(Math.random()*100)|0]; if (!r) continue;
    r.cells[2].textContent = (Math.random()*1000).toFixed(1);
    r.cells[3].style.background = `hsl(${(Math.random()*360)|0} 70% 80%)`;
  }
}, 100);
const t0 = performance.now();
setInterval(() => { $('clock').textContent = ((performance.now()-t0)/1000).toFixed(1); }, 100);
// closed + open shadow roots
class XClosed extends HTMLElement { constructor() { super(); const r = this.attachShadow({mode:'closed'});
  r.innerHTML = '<style>span{color:white;background:crimson;padding:2px 6px;font-weight:bold}</style><span>closed 0</span>';
  let n = 0; setInterval(() => { r.querySelector('span').textContent = 'closed ' + (++n); }, 300); } }
class XOpen extends HTMLElement { constructor() { super(); const r = this.attachShadow({mode:'open'});
  r.innerHTML = '<style>b{color:white;background:navy;padding:2px 6px}</style><b>open 0</b>';
  let n = 0; setInterval(() => { r.querySelector('b').textContent = 'open ' + (++n); }, 300); } }
customElements.define('x-closed', XClosed); customElements.define('x-open', XOpen);
// CSS-in-JS: insertRule into an empty <style>, then swap the class
const sheet = $('cssinjs').sheet; let ci = 0;
setInterval(() => { ci++; sheet.insertRule(`.cij-${ci}{background:hsl(${ci*37%360} 80% 60%);transform:translateX(${ci%5*6}px)}`, sheet.cssRules.length); $('cij').className = 'box cij-' + ci; }, 500);
// adoptedStyleSheets
const cs = new CSSStyleSheet(); document.adoptedStyleSheets = [cs]; let ai = 0;
setInterval(() => { ai++; cs.replaceSync(`#adopt{border:6px solid hsl(${ai*53%360} 90% 45%)}`); }, 700);
// inputs set by script (properties, not attributes)
let ii = 0;
setInterval(() => { ii++; $('txt').value = 'tick ' + ii; $('chk').checked = ii % 2 === 0; $('sel').selectedIndex = ii % 3;
  $('rng').value = String(ii * 7 % 100); $('ta').value = 'line ' + ii + '\nnext ' + (ii*2); }, 400);
// inner scroll container scrolled by script
const sc = $('scroller'); sc.innerHTML = Array.from({length: 60}, (_, i) => `<div>scroll line ${i}</div>`).join('');
let si = 0; setInterval(() => { si = (si + 7) % 900; sc.scrollTop = si; }, 200);
// svg attribute changes, details toggle, template clones
let vi = 0; setInterval(() => { vi++; $('bar').setAttribute('width', 20 + vi*13 % 180); $('svgt').textContent = 'svg ' + vi; }, 250);
setInterval(() => { $('det').open = !$('det').open; }, 1500);
setInterval(() => { const ul = $('tl'); if (ul.children.length > 4) ul.firstElementChild.remove(); ul.appendChild($('tpl').content.cloneNode(true)); }, 900);
// late font through the FontFace API (no DOM change)
setTimeout(async () => { const f = new FontFace('LateFace', 'url(/assets/late.ttf)'); await f.load(); document.fonts.add(f); }, 2000);
// frame-time probe
window.__frames = []; let last = performance.now();
(function tick(now) { window.__frames.push(now - last); last = now; requestAnimationFrame(tick); })(performance.now());

